ids = await orders_list_order_ids()
futures = [orders_get_order(order_id=str(i)) for i in ids]
rows = [await f for f in futures]
sample_keys = sorted(rows[0].keys()) if rows and isinstance(rows[0], dict) else type(rows[0]).__name__
types = {}
for r in rows:
    if isinstance(r, dict):
        for k, v in r.items():
            types.setdefault(k, set()).add(type(v).__name__)
return {
    "n_ids": len(ids),
    "n_unique_ids": len(set(map(str, ids))),
    "n_rows": len(rows),
    "keys": sample_keys,
    "types": {k: sorted(v) for k, v in types.items()},
    "statuses": sorted({str(r.get("status")) for r in rows if isinstance(r, dict)}),
    "regions": sorted({str(r.get("region")) for r in rows if isinstance(r, dict)}),
    "errors": sum(1 for r in rows if not isinstance(r, dict) or r.get("error")),
}

